"""單價分析（CostBreakdownList）的重算規則：改組成列的數量或單價後，重算該分析的單價（`edit.py` 用）。

規則是從三份 PCCES 匯出檔靜態驗出來的（ArchEx001、Class01、實案，另有 PCCES 改值後的匯出檔當對照；
覆蓋數與 PCCES 實測見 notes\\決策\\〈改單價分析組成照PCCES規則重算分析單價〉）。
位數一律取 CostBreakdownList 的 quantityDisplayDecimal／unitPriceDisplayDecimal／itemAmountDisplayDecimal：

1. 組成列複價＝round(round(數量, 數量位數) × round(單價, 單價位數), 複價位數)，四捨五入遠離零。
   巢狀分析列（itemKind=analysis）也一樣，它的單價是子分析算出的單價。
2. % 類（variableSumPercentage，工具損耗、零星工料這類）每個分析至多一列、排在最後。S＝其他各列複價和，
   分析單價 P＝round(S ×（1＋Percent/100）÷ analysisOutputQuantity, 單價位數)，
   這一列的單價＝複價＝P × analysisOutputQuantity − S：補成剛好整除，不是 round(S × Percent%)。
   兩者只在 analysisOutputQuantity≠1 時不同（清除及掘除以 10000 M2 為單位，7480 不是 4576）。
3. 沒有 % 類的分析：P＝round(各列複價和 ÷ analysisOutputQuantity, 單價位數)。
4. 詳細表用到這個分析的葉項，單價＝P。

人機料雜比例（LabourRatio 等）的算法沒推出來，呼叫端照抄並講明。
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

from .document import Item, ItemList

PCT_KIND = "variableSumPercentage"
VARIABLE_KIND = "variablePrice"
ANALYSIS_KIND = "analysis"
GENERAL_KIND = "general"


class AnalysisRuleError(ValueError):
    """這個分析照規則算不了（結構跟樣本不同）；訊息是原因。"""


@dataclass(frozen=True)
class Digits:
    quantity: int
    price: int
    amount: int


def digits(cbl: ItemList) -> Digits:
    a = cbl.attrs
    return Digits(
        int(a.get("quantityDisplayDecimal", "0") or 0),
        int(a.get("unitPriceDisplayDecimal", "0") or 0),
        int(a.get("itemAmountDisplayDecimal", "0") or 0),
    )


def rnd(v: Decimal, places: int) -> Decimal:
    return v.quantize(Decimal(1).scaleb(-places), ROUND_HALF_UP)


def code(it: Item) -> str:
    return it.attrs.get("itemCode", "").strip()


def kind(it: Item) -> str:
    return it.attrs.get("itemKind", "").strip()


def name(it: Item) -> str:
    return (it.value("Description", "zh-TW") or "").strip()


def output_quantity(w: Item) -> Decimal:
    s = w.attrs.get("analysisOutputQuantity", "1").strip() or "1"
    q = Decimal(s)
    if q <= 0:
        raise AnalysisRuleError(f"analysisOutputQuantity 是 {s}，不能拿來除")
    return q


def row_amount(quantity: Decimal, price: Decimal, d: Digits) -> Decimal:
    """組成列複價（模組說明第 1 條）：數量、單價都先進位再乘。"""
    return rnd(rnd(quantity, d.quantity) * rnd(price, d.price), d.amount)


def _need(it: Item, tag: str) -> Decimal:
    v = it.decimal(tag)
    if v is None:
        raise AnalysisRuleError(f"組成列 {code(it)} {name(it)} 沒有 {tag}")
    return v


@dataclass
class Computed:
    amounts: list[Decimal]  # 每一列組成的複價（含 % 類），順序同 children
    price: Decimal  # 分析單價 P


def compute(w: Item, d: Digits) -> Computed:
    """照模組說明的規則，用各列現在的數量與單價算一次；結構跟樣本不同就丟 AnalysisRuleError。"""
    aoq = output_quantity(w)
    rows = w.children
    pct = [i for i, c in enumerate(rows) if kind(c) == PCT_KIND]
    if len(pct) > 1:
        raise AnalysisRuleError(f"有 {len(pct)} 列 % 類，樣本的分析每個至多一列")
    if pct and pct[0] != len(rows) - 1:
        raise AnalysisRuleError("% 類不在最後一列，樣本都在最後")
    amounts = [row_amount(_need(c, "Quantity"), _need(c, "Price"), d) for c in rows if kind(c) != PCT_KIND]
    s = sum(amounts, Decimal(0))
    if not pct:
        return Computed(amounts, rnd(s / aoq, d.price))
    c = rows[pct[0]]
    if _need(c, "Quantity") != 1:
        raise AnalysisRuleError(f"% 類 {code(c)} {name(c)} 的數量不是 1，樣本都是 1")
    percent = _need(c, "Percent")
    p = rnd(s * (1 + percent / 100) / aoq, d.price)
    return Computed(amounts + [p * aoq - s], p)


def mismatches(w: Item, d: Digits) -> list[str]:
    """底稿的值照規則重現不了的地方；空清單代表這個分析的每一列複價與單價都對得上。"""
    try:
        got = compute(w, d)
    except AnalysisRuleError as exc:
        return [str(exc)]
    out: list[str] = []
    for c, a in zip(w.children, got.amounts):
        if c.decimal("Amount") != a:
            out.append(f"{code(c)} {name(c)} 複價底稿 {c.value('Amount')}、照規則 {a}")
        if kind(c) == PCT_KIND and c.decimal("Price") != c.decimal("Amount"):
            out.append(f"% 類 {code(c)} {name(c)} 的單價不等於複價")
    if w.decimal("Price") != got.price:
        out.append(f"分析單價底稿 {w.value('Price')}、照規則 {got.price}")
    return out


def same_analysis(a: Item, b: Item) -> bool:
    """同一個分析被兩列詳細表用到時 PCCES 輸出兩份；兩份的組成與單價要一模一樣才當成同一個分析。"""

    def sig(w: Item):
        return (
            w.attrs.get("analysisOutputQuantity"), w.value("Price"),
            [(code(c), kind(c), c.value("Quantity"), c.value("Price"), c.value("Amount"), c.value("Percent"),
              sig(c) if c.children else None) for c in w.children],
        )

    return sig(a) == sig(b)
